"""Валидация проекта: схема и связность разделов (T1-05, G1-05).

Валидатор собирает **все** замечания сразу, а не падает на первом: UI должен
показать список и дать переход к каждому полю. Путь замечания совпадает
с путём в JSON-документе (``agents.0.sensors.1.link``).
"""

from __future__ import annotations

from dataclasses import dataclass, field
from typing import Any

from pydantic import ValidationError

from simorph.core.errors import ProjectValidationError, UnsupportedVersionError
from simorph.core.issues import (
    Issue,
    IssueCode,
    Severity,
    has_errors,
    issue,
    issues_from_validation_error,
)
from simorph.core.migrations import payload_version
from simorph.core.models.project import ProjectDocument
from simorph.core.schema_version import CURRENT_VERSION, is_current, is_known


@dataclass(frozen=True, slots=True)
class ValidationReport:
    """Итог проверки документа."""

    issues: list[Issue] = field(default_factory=list)
    version: str = CURRENT_VERSION

    @property
    def ok(self) -> bool:
        """Нет ошибок (предупреждения не мешают)."""
        return not has_errors(self.issues)

    @property
    def errors(self) -> list[Issue]:
        return [item for item in self.issues if item.severity is Severity.ERROR]

    @property
    def warnings(self) -> list[Issue]:
        return [item for item in self.issues if item.severity is Severity.WARNING]

    def to_dict(self) -> dict[str, Any]:
        """Представление для JSON-вывода CLI."""
        return {
            "ok": self.ok,
            "version": self.version,
            "errors": len(self.errors),
            "warnings": len(self.warnings),
            "issues": [item.to_dict() for item in self.issues],
        }


def _duplicates(ids: list[str]) -> list[str]:
    """Идентификаторы, встречающиеся больше одного раза."""
    seen: set[str] = set()
    repeated: list[str] = []
    for item in ids:
        if item in seen and item not in repeated:
            repeated.append(item)
        seen.add(item)
    return repeated


def _check_unique(ids: list[str], path: str, kind: str) -> list[Issue]:
    return [
        issue(IssueCode.DUPLICATE_ID, f"{path}.{name}", f"повторяющийся идентификатор {kind}")
        for name in _duplicates(ids)
    ]


def _check_agent(agent_index: int, document: ProjectDocument) -> list[Issue]:
    """Проверяет внутренние ссылки агента."""
    agent = document.agents[agent_index]
    prefix = f"agents.{agent_index}"
    issues: list[Issue] = []
    issues += _check_unique([link.id for link in agent.links], f"{prefix}.links", "звена")
    issues += _check_unique([joint.id for joint in agent.joints], f"{prefix}.joints", "сустава")
    issues += _check_unique([item.id for item in agent.sensors], f"{prefix}.sensors", "сенсора")
    issues += _check_unique(
        [item.id for item in agent.actuators], f"{prefix}.actuators", "актуатора"
    )
    issues += _check_unique(
        [item.id for item in agent.links_comm], f"{prefix}.links_comm", "канала связи"
    )

    link_ids = {link.id for link in agent.links}
    for joint_index, joint in enumerate(agent.joints):
        for field_name in ("parent", "child"):
            target = getattr(joint, field_name)
            if link_ids and target not in link_ids:
                issues.append(
                    issue(
                        IssueCode.DANGLING_REFERENCE,
                        f"{prefix}.joints.{joint_index}.{field_name}",
                        f"сустав ссылается на несуществующее звено {target!r}",
                    )
                )

    joint_ids = {joint.id for joint in agent.joints}
    for sensor_index, sensor in enumerate(agent.sensors):
        if sensor.link is not None and link_ids and sensor.link not in link_ids:
            issues.append(
                issue(
                    IssueCode.DANGLING_REFERENCE,
                    f"{prefix}.sensors.{sensor_index}.link",
                    f"сенсор закреплён на несуществующем звене {sensor.link!r}",
                )
            )
    for actuator_index, actuator in enumerate(agent.actuators):
        if actuator.joint is not None and joint_ids and actuator.joint not in joint_ids:
            issues.append(
                issue(
                    IssueCode.DANGLING_REFERENCE,
                    f"{prefix}.actuators.{actuator_index}.joint",
                    f"актуатор ссылается на несуществующий сустав {actuator.joint!r}",
                )
            )
    return issues


def _check_world(document: ProjectDocument) -> list[Issue]:
    """Проверяет уникальность идентификаторов мира и ссылки зданий."""
    world = document.world
    issues: list[Issue] = []
    issues += _check_unique([zone.id for zone in world.zones], "world.zones", "зоны")
    issues += _check_unique([item.id for item in world.buildings], "world.buildings", "здания")
    issues += _check_unique([item.id for item in world.equipment], "world.equipment", "оборудования")
    issues += _check_unique([item.id for item in world.trees], "world.trees", "дерева")
    issues += _check_unique([item.id for item in world.water], "world.water", "водоёма")

    zone_ids = {zone.id for zone in world.zones}
    for index, building in enumerate(world.buildings):
        if zone_ids and building.zone not in zone_ids:
            issues.append(
                issue(
                    IssueCode.DANGLING_REFERENCE,
                    f"world.buildings.{index}.zone",
                    f"здание ссылается на несуществующую зону {building.zone!r}",
                )
            )
    return issues


def _check_mission_graph(
    mission_index: int,
    exercise_index: int,
    document: ProjectDocument,
) -> list[Issue]:
    """Проверяет ссылки ``next``, достижимость и циклы в графе миссии."""
    exercise = document.exercises[exercise_index]
    mission = exercise.missions[mission_index]
    prefix = f"exercises.{exercise_index}.missions.{mission_index}"
    issues: list[Issue] = []

    issues += _check_unique([item.id for item in mission.elements], f"{prefix}.elements", "элемента")

    elements = {item.id: item for item in mission.elements}
    for index, element in enumerate(mission.elements):
        for next_id in element.next:
            if next_id not in elements:
                issues.append(
                    issue(
                        IssueCode.DANGLING_REFERENCE,
                        f"{prefix}.elements.{index}.next",
                        f"переход ведёт на несуществующий элемент {next_id!r}",
                    )
                )

    starts = [item for item in mission.elements if item.type == "start"]
    if not starts:
        issues.append(
            issue(IssueCode.INVALID_GRAPH, f"{prefix}.elements", "в миссии нет элемента 'start'")
        )
    elif len(starts) > 1:
        issues.append(
            issue(
                IssueCode.INVALID_GRAPH,
                f"{prefix}.elements",
                f"в миссии несколько элементов 'start': {len(starts)}",
            )
        )

    issues += [
        issue(
            IssueCode.INVALID_GRAPH,
            f"{prefix}.elements.{index}.next",
            "цикл допустим только через элемент 'loop'",
        )
        for index in _cycle_elements(mission.elements)
    ]

    reachable = _reachable_from_start(mission.elements)
    for index, element in enumerate(mission.elements):
        if element.id not in reachable:
            issues.append(
                issue(
                    IssueCode.INVALID_GRAPH,
                    f"{prefix}.elements.{index}",
                    f"элемент {element.id!r} недостижим из 'start'",
                    severity=Severity.WARNING,
                )
            )
    return issues


def _cycle_elements(elements: list[Any]) -> list[int]:
    """Индексы элементов, участвующих в цикле не через ``loop``."""
    by_id = {item.id: item for item in elements}
    state: dict[str, int] = {}
    offenders: set[str] = set()

    def visit(node_id: str, path: list[str]) -> None:
        if state.get(node_id) == 1:
            return
        state[node_id] = 1
        path.append(node_id)
        node = by_id.get(node_id)
        if node is not None:
            for next_id in node.next:
                if next_id not in by_id:
                    continue
                if state.get(next_id) == 1:
                    if node.type != "loop":
                        start = path.index(next_id) if next_id in path else 0
                        offenders.update(path[start:])
                else:
                    visit(next_id, path)
        path.pop()
        state[node_id] = 2

    for item in elements:
        visit(item.id, [])
    return [index for index, item in enumerate(elements) if item.id in offenders]


def _reachable_from_start(elements: list[Any]) -> set[str]:
    """Множество идентификаторов, достижимых из ``start``."""
    by_id = {item.id: item for item in elements}
    starts = [item.id for item in elements if item.type == "start"]
    reached: set[str] = set()
    stack = list(starts)
    while stack:
        node_id = stack.pop()
        if node_id in reached:
            continue
        reached.add(node_id)
        node = by_id.get(node_id)
        if node is not None:
            stack.extend(next_id for next_id in node.next if next_id in by_id)
    return reached


def _check_exercise(exercise_index: int, document: ProjectDocument) -> list[Issue]:
    """Проверяет связи упражнения с миром, агентами и миссиями."""
    exercise = document.exercises[exercise_index]
    prefix = f"exercises.{exercise_index}"
    issues: list[Issue] = []

    if exercise.world_id != document.world.world_id:
        issues.append(
            issue(
                IssueCode.DANGLING_REFERENCE,
                f"{prefix}.world_id",
                f"упражнение ссылается на мир {exercise.world_id!r}, "
                f"а в проекте мир {document.world.world_id!r}",
            )
        )

    agent_ids = {agent.agent_id for agent in document.agents}
    for index, agent_id in enumerate(exercise.agents):
        if agent_ids and agent_id not in agent_ids:
            issues.append(
                issue(
                    IssueCode.DANGLING_REFERENCE,
                    f"{prefix}.agents.{index}",
                    f"упражнение ссылается на несуществующего агента {agent_id!r}",
                )
            )

    issues += _check_unique([item.mission_id for item in exercise.missions], f"{prefix}.missions", "миссии")

    zone_ids = {zone.id for zone in document.world.zones}
    sensors_by_agent = {
        agent.agent_id: {sensor.id for sensor in agent.sensors} for agent in document.agents
    }
    for mission_index, mission in enumerate(exercise.missions):
        if mission.agent_id not in agent_ids and agent_ids:
            issues.append(
                issue(
                    IssueCode.DANGLING_REFERENCE,
                    f"{prefix}.missions.{mission_index}.agent_id",
                    f"миссия назначена несуществующему агенту {mission.agent_id!r}",
                )
            )
        issues += _check_mission_graph(mission_index, exercise_index, document)

        known_sensors = sensors_by_agent.get(mission.agent_id, set())
        for element_index, element in enumerate(mission.elements):
            element_path = f"{prefix}.missions.{mission_index}.elements.{element_index}"
            if element.zone is not None and zone_ids and element.zone not in zone_ids:
                issues.append(
                    issue(
                        IssueCode.DANGLING_REFERENCE,
                        f"{element_path}.zone",
                        f"элемент ссылается на несуществующую зону {element.zone!r}",
                    )
                )
            if element.sensor is not None and known_sensors and element.sensor not in known_sensors:
                issues.append(
                    issue(
                        IssueCode.DANGLING_REFERENCE,
                        f"{element_path}.sensor",
                        f"элемент ссылается на сенсор {element.sensor!r}, "
                        f"которого нет у агента {mission.agent_id!r}",
                    )
                )
    return issues


def _check_pipeline(pipeline_index: int, document: ProjectDocument) -> list[Issue]:
    """Проверяет узлы, рёбра и бюджеты конвейера."""
    pipeline = document.pipelines[pipeline_index]
    prefix = f"pipelines.{pipeline_index}"
    issues = _check_unique([node.id for node in pipeline.nodes], f"{prefix}.nodes", "узла")

    node_ids = {node.id for node in pipeline.nodes}
    for edge_index, edge in enumerate(pipeline.edges):
        for field_name, value in (("from", edge.src), ("to", edge.dst)):
            node_id = value.split(".", 1)[0]
            if node_id not in node_ids:
                issues.append(
                    issue(
                        IssueCode.DANGLING_REFERENCE,
                        f"{prefix}.edges.{edge_index}.{field_name}",
                        f"ребро ссылается на несуществующий узел {node_id!r}",
                    )
                )

    issues += _check_pipeline_cycles(pipeline, prefix)
    return issues


def _check_pipeline_cycles(pipeline: Any, prefix: str) -> list[Issue]:
    """Ищет циклы в графе узлов конвейера."""
    graph: dict[str, set[str]] = {node.id: set() for node in pipeline.nodes}
    for edge in pipeline.edges:
        src = edge.src.split(".", 1)[0]
        dst = edge.dst.split(".", 1)[0]
        if src in graph and dst in graph:
            graph[src].add(dst)

    state: dict[str, int] = {}
    in_cycle: set[str] = set()

    def visit(node_id: str, path: list[str]) -> None:
        state[node_id] = 1
        path.append(node_id)
        for next_id in graph.get(node_id, ()):
            if state.get(next_id) == 1:
                in_cycle.update(path[path.index(next_id) :])
            elif state.get(next_id, 0) == 0:
                visit(next_id, path)
        path.pop()
        state[node_id] = 2

    for node_id in graph:
        if state.get(node_id, 0) == 0:
            visit(node_id, [])

    index_by_id = {node.id: index for index, node in enumerate(pipeline.nodes)}
    return [
        issue(IssueCode.INVALID_GRAPH, f"{prefix}.nodes.{index_by_id[name]}", "цикл в графе конвейера")
        for name in sorted(in_cycle, key=lambda item: index_by_id[item])
    ]


def _check_report(report_index: int, document: ProjectDocument) -> list[Issue]:
    """Проверяет ссылки отчёта на конвейеры."""
    report = document.reports[report_index]
    prefix = f"reports.{report_index}"
    issues: list[Issue] = []
    pipeline_ids = {pipeline.pipeline_id for pipeline in document.pipelines}
    for index, pipeline_id in enumerate(report.pipeline_ids):
        if pipeline_ids and pipeline_id not in pipeline_ids:
            issues.append(
                issue(
                    IssueCode.DANGLING_REFERENCE,
                    f"{prefix}.pipeline_ids.{index}",
                    f"отчёт ссылается на несуществующий конвейер {pipeline_id!r}",
                )
            )
    return issues


def validate_document(document: ProjectDocument) -> ValidationReport:
    """Проверяет связи между разделами готового документа."""
    issues: list[Issue] = []

    issues += _check_unique([agent.agent_id for agent in document.agents], "agents", "агента")
    issues += _check_unique(
        [exercise.exercise_id for exercise in document.exercises], "exercises", "упражнения"
    )
    issues += _check_unique(
        [pipeline.pipeline_id for pipeline in document.pipelines], "pipelines", "конвейера"
    )
    issues += _check_unique([report.report_id for report in document.reports], "reports", "отчёта")

    issues += _check_world(document)
    for index in range(len(document.agents)):
        issues += _check_agent(index, document)
    for index in range(len(document.exercises)):
        issues += _check_exercise(index, document)
    for index in range(len(document.pipelines)):
        issues += _check_pipeline(index, document)
    for index in range(len(document.reports)):
        issues += _check_report(index, document)

    return ValidationReport(issues=issues, version=document.schema_version)


def validate_payload(payload: dict[str, Any]) -> ValidationReport:
    """Полная проверка: версия → схема → связность.

    Неизвестная версия и несоответствие схеме не прерывают проверку связности,
    если документ удалось построить.
    """
    issues: list[Issue] = []

    try:
        version = payload_version(payload)
    except UnsupportedVersionError as exc:
        return ValidationReport(
            issues=[issue(IssueCode.UNKNOWN_VERSION, "schema_version", str(exc))],
            version=getattr(exc, "version", "unknown"),
        )

    if not is_current(version):
        if is_known(version):
            issues.append(
                issue(
                    IssueCode.UNKNOWN_VERSION,
                    "schema_version",
                    f"версия {version} требует миграции до {CURRENT_VERSION}",
                    severity=Severity.WARNING,
                )
            )
        else:
            issues.append(
                issue(
                    IssueCode.UNKNOWN_VERSION,
                    "schema_version",
                    f"неизвестная или более новая версия схемы: {version}",
                )
            )
            return ValidationReport(issues=issues, version=version)

    try:
        document = ProjectDocument.model_validate(payload)
    except ValidationError as exc:
        issues += issues_from_validation_error(exc)
        return ValidationReport(issues=issues, version=version)

    report = validate_document(document)
    return ValidationReport(issues=issues + report.issues, version=version)


def ensure_valid(document: ProjectDocument) -> None:
    """Проверяет документ и поднимает исключение при ошибках.

    Raises:
        ProjectValidationError: есть хотя бы одна ошибка.
    """
    report = validate_document(document)
    if not report.ok:
        raise ProjectValidationError(
            f"проект не прошёл проверку связности: {len(report.errors)} ошибок",
            issues=report.issues,
        )

