    """Windows: ждём объект процесса, не блокируясь."""
    if sys.platform != "win32":
        raise OSError("проверка процессов Windows доступна только на Windows")
    import ctypes

    synchronize = 0x00100000
    still_active = 0x00000102
    kernel32 = ctypes.windll.kernel32
    handle = kernel32.OpenProcess(synchronize, False, pid)
    if not handle:
        return False
    try:
        return bool(kernel32.WaitForSingleObject(handle, 0) == still_active)
    finally:
        kernel32.CloseHandle(handle)


def _process_alive_posix(pid: int) -> bool:  # pragma: no cover - ветка POSIX
    """POSIX: сигнал 0 проверяет существование процесса."""
    try:
        os.kill(pid, 0)
    except ProcessLookupError:
        return False
    except PermissionError:
        return True
    return True


