def mergeWith(self, other: QUndoCommand) -> bool:  # noqa: N802 - API Qt
    if not isinstance(other, SetValueCommand):
        return False
    if other._path != self._path:
        return False
    self._value = other._value
    self._after = other._after
    return True

def redo(self) -> None:
    if self._after is None:
        if self._before is None:
