class SetValueCommand(QUndoCommand):
    """Правка одного значения по пути."""

    def __init__(
        self,
        store: DocumentStore,
        path: str,
        value: Any,
        *,
        text: str = "",
    ) -> None:
        super().__init__(text)
        self._store = store
        self._path = path
        self._value = value
        self._before: ProjectDocument | None = None
        self._after: ProjectDocument | None = None

    def redo(self) -> None:
        if self._after is None:
            if self._before is None:
                self._before = self._store.document
            self._after = write_value(self._before, self._path, self._value)
        self._store._replace(self._after)

    def undo(self) -> None:
        if self._before is not None:
            self._store._replace(self._before)

